import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Cz0TtJv6.js";const u=JSON.parse('{"title":"Dashboard guide","description":"Tab-by-tab tour of the DLMM Bot ops dashboard — Overview, Positions, Activity, Analytics, Research, Errors, Changes, Settings, Wiki — plus the setup wizard, encrypted wallet, and HALT.","frontmatter":{"title":"Dashboard guide","description":"Tab-by-tab tour of the DLMM Bot ops dashboard — Overview, Positions, Activity, Analytics, Research, Errors, Changes, Settings, Wiki — plus the setup wizard, encrypted wallet, and HALT."},"headers":[],"relativePath":"dashboard.md","filePath":"dashboard.md","lastUpdated":1786716878000}'),s={name:"dashboard.md"};function i(n,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="dashboard-guide" tabindex="-1">Dashboard guide <a class="header-anchor" href="#dashboard-guide" aria-label="Permalink to &quot;Dashboard guide&quot;">​</a></h1><p>The dashboard is the web UI that ships with the bot: a live window onto the farmer process, read-only against the SQLite ledger, plus settings writes, the setup wizard, and encrypted wallet management. On Railway it&#39;s your public HTTPS URL; locally it&#39;s <code>http://localhost:8787/?token=…</code> (see <a href="./advanced">Advanced setup</a>).</p><p>You don&#39;t need every tab every day. <strong>Overview</strong> for &quot;am I ok?&quot;, <strong>Positions</strong> for open trades, <strong>Activity</strong> when something weird happens, <strong>Wiki</strong> when you forget a rule.</p><h2 id="first-login-the-setup-wizard" tabindex="-1">First login: the setup wizard <a class="header-anchor" href="#first-login-the-setup-wizard" aria-label="Permalink to &quot;First login: the setup wizard&quot;">​</a></h2><p>When RPC and wallet are missing, first login opens a wizard that walks through:</p><ol><li><strong>Confirm the dash token</strong> — from Railway deploy logs (<code>generated DASH_TOKEN=…</code>) or your <code>DASH_TOKEN</code> env var.</li><li><strong>RPC &amp; APIs</strong> — paste a <a href="https://www.helius.dev/" target="_blank" rel="noreferrer">Helius</a> mainnet RPC URL, a <a href="https://developers.jup.ag/portal" target="_blank" rel="noreferrer">Jupiter</a> API key (required), and optionally <a href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">GMGN</a> (free — see <a href="./api-keys">API keys</a>).</li><li><strong>Wallet</strong> — create a new Solana keypair, or import a Phantom base58 private key. Either way it&#39;s encrypted with a passphrase (AES-256-GCM) and stored as <code>wallet.enc.json</code> on your data volume. The wizard forces a password retype and shows a one-time backup.</li><li><strong>Choose paper or live</strong> — live still needs the <a href="./risk#paper-first-the-promotion-gate">double lock</a>.</li><li>Optionally <strong>unlock</strong> the wallet into <code>.env</code> for trading (or set <code>WALLET_PASSPHRASE</code> on Railway to auto-unlock on boot).</li></ol><div class="danger custom-block"><p class="custom-block-title">Burner only</p><p>Create a fresh wallet or import a burner. Never your main wallet.</p></div><h2 id="header-the-health-lights" tabindex="-1">Header: the health lights <a class="header-anchor" href="#header-the-health-lights" aria-label="Permalink to &quot;Header: the health lights&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pill / control</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>ON/OFF</strong></td><td>Soft pause. OFF = no new trades, no exits initiated; positions stay open and watched (<code>PAUSE</code> file).</td></tr><tr><td><strong>HALT</strong> (red)</td><td>Emergency close-all: confirm with your dash token → the farmer closes every open position, swaps to SOL, and idles until Resume. Separate from ON/OFF.</td></tr><tr><td><strong>HB</strong></td><td>Farmer alive? Shows seconds since the last finished tick — green = fresh, red = stuck or missing. It is tick age, not a wall clock.</td></tr><tr><td><strong>WS</strong></td><td>This browser page&#39;s live websocket feed.</td></tr><tr><td><strong>PAPER / LIVE</strong></td><td>Current mode.</td></tr><tr><td><strong>BRAKE</strong></td><td>Appears when the cluster brake has paused new entries.</td></tr><tr><td><strong>Build pill + Auto switch</strong></td><td>Are you current with GitHub? The Auto on/off switch beside it chooses auto-pull vs Approve-on-Changes.</td></tr><tr><td><strong>Host / wallet chip</strong></td><td>Which machine, and the wallet when known.</td></tr></tbody></table><h2 id="the-tabs" tabindex="-1">The tabs <a class="header-anchor" href="#the-tabs" aria-label="Permalink to &quot;The tabs&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The money snapshot: account value, open profit with slot occupancy (e.g. <code>3 of 5 · 2 free</code>), and the equity chart. Engine ON/OFF and HALT live in the header, so this tab plus the header answers &quot;is everything fine?&quot; in one glance.</p><h3 id="positions" tabindex="-1">Positions <a class="header-anchor" href="#positions" aria-label="Permalink to &quot;Positions&quot;">​</a></h3><p>Open positions (each with its slot badge) and recent closes. The range bar on an open position splits by color: <strong>purple ≈ SOL still waiting</strong> in bins below price, <strong>blue ≈ already converted to token</strong> as price walked down through the bins. Close rows separate <strong>Move</strong> (deposit/IL) from <strong>Fees</strong> so you can see <em>why</em> a close netted what it did.</p><h3 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;Activity&quot;">​</a></h3><p>The live play-by-play: entries, exits, claims, skips, follow-chain events. SOL amounts are color-coded — green for inflows/wins, blue for capital deployed (entries), red only for actual losses. On-chain rows link to Solscan.</p><h3 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h3><p>Why you made or lost SOL: exits by reason (P0–P5), performance by sleeve, and skip statistics. This is where you check whether a knob change did anything before touching the next one.</p><h3 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h3><p>Public X (Twitter) credits for people whose playbooks informed the strategy. <strong>Not partners, not trade signals.</strong></p><h3 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h3><p>Structured runtime failures streamed over WebSocket. Each row carries a plain label — <strong>Transient</strong> (API blip, auto-retries), <strong>Degraded</strong> (partial), <strong>Needs attention</strong> (review) — plus the stack, mint/pool context, a copy-dump button for bug reports, and a shortcut to open a GitHub issue. Dismiss what you&#39;ve handled.</p><h3 id="changes-changelog" tabindex="-1">Changes (Changelog) <a class="header-anchor" href="#changes-changelog" aria-label="Permalink to &quot;Changes (Changelog)&quot;">​</a></h3><p>Pending git updates from GitHub. Each commit gets <strong>risk chips</strong> (<code>strategy</code> / <code>deps</code> / <code>deploy</code> / <code>core</code> / <code>dash</code> / <code>docs</code>) — a quick &quot;how spicy is this update?&quot; hint, not a substitute for reading the subjects. With auto-update <strong>on</strong> (the default), the deploy watcher pulls, rebuilds, and restarts on its own; with it <strong>off</strong>, this tab shows BEHIND and an <strong>Approve</strong> button pulls that tip when you click it.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>Two halves:</p><ul><li><strong>Bot settings</strong> — the strategy knobs (sizing incl. Kelly, risk brakes, vetting filters, sleeves), persisted to <code>data/config.toml</code> on your volume and hot-reloaded by the farmer within seconds. Also home of <strong><a href="./profiles">Profiles</a></strong>: official Conservative / Balanced / Aggressive packs, your own local saves, and the community gallery with a diff preview before Apply. Profiles never flip paper/live or touch secrets (see <a href="./fees">Fees</a> for what stays fixed).</li><li><strong>Wallet &amp; secrets</strong> — the encrypted wallet vault (create / import from Phantom / unlock), <code>RPC_URL</code>, API keys, and the auto-update preference.</li></ul><p>Settings writes go to the <code>data/</code> volume, never the git checkout — so the build pill showing DIRTY always means real code drift, not knob changes.</p><h3 id="wiki" tabindex="-1">Wiki <a class="header-anchor" href="#wiki" aria-label="Permalink to &quot;Wiki&quot;">​</a></h3><p>The in-dashboard operator manual — a friendlier mirror of <a href="https://github.com/CryptoGnome/dlmmbot/blob/master/STRATEGY.md" target="_blank" rel="noreferrer">STRATEGY.md</a>: big picture, sleeves, scanning, entries, the P0–P5 ladder, follow mode, sizing, skips, accounting, and a glossary. It&#39;s kept in sync with the code whenever behavior changes.</p><h2 id="encrypted-wallet-create-import-unlock" tabindex="-1">Encrypted wallet: create, import, unlock <a class="header-anchor" href="#encrypted-wallet-create-import-unlock" aria-label="Permalink to &quot;Encrypted wallet: create, import, unlock&quot;">​</a></h2><p>The dashboard&#39;s wallet vault is the recommended way to hold the live key:</p><ul><li><strong>Create</strong> — generates a fresh keypair in the browser flow, encrypts it with your passphrase, stores only <code>wallet.enc.json</code> on the volume.</li><li><strong>Import</strong> — paste a Phantom base58 private key (a burner!); same encryption. The plaintext never lands on disk unencrypted.</li><li><strong>Unlock</strong> — decrypts into the runtime <code>.env</code> so the farmer can sign. On Railway, setting <code>WALLET_PASSPHRASE</code> as a service variable auto-unlocks on boot; otherwise unlock manually after each restart.</li></ul><p>Keys live on <strong>your</strong> volume/host — this is not a hosted custody service.</p><h2 id="halting-from-the-dashboard" tabindex="-1">Halting from the dashboard <a class="header-anchor" href="#halting-from-the-dashboard" aria-label="Permalink to &quot;Halting from the dashboard&quot;">​</a></h2><p>The red <strong>HALT</strong> button asks for your dash token, then writes the same <code>HALT</code> file as <code>npm run halt</code>: the farmer closes every open position, swaps residuals to SOL, and idles. <strong>Resume</strong> clears it. Use ON/OFF instead when you just want to stop <em>new</em> activity without closing the book — see <a href="./risk#halt-vs-pause-vs-off">HALT vs PAUSE vs OFF</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./easy">Easy setup (Railway)</a> — getting a dashboard URL in the first place</li><li><a href="./advanced">Advanced setup</a> — local dashboard, tunnels, PM2</li><li><a href="./profiles">Settings profiles</a> — packs, saving, community sharing</li><li><a href="./configuration">Configuration reference</a> — what every Bot-settings knob does</li><li><a href="./risk">Risk &amp; sizing</a> — HALT/PAUSE semantics and the brakes</li></ul>',38)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
